1341 :                         && (chars[i] < 'A' || chars[i] > 'F')) {
1342 :                         return false;
1343 :                     }
1344 :                 }
1345 :                 return true;
1346 :             }
1347 :         }
1348 :         sz--; // don't want to loop to the last char, check it afterwords
