1360 :                     // two decimal points or dec in exponent   
1361 :                     return false;
1362 :                 }
1363 :                 hasDecPoint = true;
1364 :             } else if (chars[i] == 'e' || chars[i] == 'E') {
1365 :                 // we've already taken care of hex.
1366 :                 if (hasExp) {
1367 :                     // two E's
1368 :                     return false;
1369 :                 }
1370 :                 if (!foundDigit) {
1371 :                     return false;
1372 :                 }
1373 :                 hasExp = true;
