1376 :                 if (!allowSigns) {
1377 :                     return false;
1378 :                 }
1379 :                 allowSigns = false;
1380 :                 foundDigit = false; // we need a digit after the E
1381 :             } else {
1382 :                 return false;
1383 :             }
1384 :             i++;
1385 :         }
1386 :         if (i < chars.length) {
1387 :             if (chars[i] >= '0' && chars[i] <= '9') {
1388 :                 // no type qualifier, OK
1389 :                 return true;
1390 :             }
1391 :             if (chars[i] == 'e' || chars[i] == 'E') {
1392 :                 // can't have an E at the last byte
1393 :                 return false;
1394 :             }
1395 :             if (chars[i] == '.') {
1396 :                 if (hasDecPoint || hasExp) {
1397 :                     // two decimal points or dec in exponent
1398 :                     return false;
1399 :                 }
1400 :                 // single trailing decimal point after non-exponent is ok
1401 :                 return foundDigit;
1402 :             }
1403 :             if (!allowSigns
1404 :                 && (chars[i] == 'd'
1405 :                     || chars[i] == 'D'
1406 :                     || chars[i] == 'f'
1407 :                     || chars[i] == 'F')) {
1408 :                 return foundDigit;
1409 :             }
1410 :             if (chars[i] == 'l'
1411 :                 || chars[i] == 'L') {
1412 :                 // not allowing L with an exponent or decimal point
1413 :                 return foundDigit && !hasExp;
1414 :             }
1415 :             // last character is illegal
1416 :             return false;
1417 :         }
1418 :         // allowSigns is true iff the val ends in 'E'
1419 :         // found digit it to make sure weird stuff like '.' and '1E-' doesn't pass
1420 :         return !allowSigns && foundDigit;
1421 :     }"

